    "slug": "details-grade-explained",
    "title": "What Does a Details Grade Mean for a Coin?",
    "excerpt": "Learn about understanding a Details grade: check the evidence, avoid common mistakes and keep clear records before deciding what to buy, sell or keep.",
    "tags": [
      "Grading & appraisal",
      "US"
    ],
    "market": "US",
    "date": "2026-10-06",
