        "text": "Choose the least intrusive method that answers the question. If better lighting, a clearer photograph or a more suitable reference would resolve the problem, use that before changing a holder or surface. In deciding whether to clean an old coin, protecting the original evidence is part of reaching a reliable conclusion."
