            "question": "Can a photograph settle the question on its own?",
            "answer": "A photograph can help with a Morgan dollar, but its usefulness depends on the visible detail and the question being asked. Request complete views and a relevant close-up when necessary. If the outcome depends on an unseen surface, an exact measurement or physical authentication, explain that limitation and seek the appropriate assessment."
